#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> v;
    v.push_back({a});
    v.push_back({b});
    v.push_back({c});

    for (int &x : v) {
        x = x * 2;
    }

    for (int x : v) {
        cout << x << endl;
    }
    return 0;
}
